#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: ClaimSale one-time owner setup (TECH_STACK §11, S35, S36).
# Run from the repository root on your own machine: scripts/setup.sh
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10

ACCOUNT_ID="e89111551171752d4230693ae0c83ed6" # AntiTcb (TECH_STACK S30)
REQUIRED_CHECKS=(
  "Format, lint, types, guards"
  "Unit + browser tests (coverage)"
  "Workers integration tests"
  "E2E (local stack)"
)
export CLOUDFLARE_ACCOUNT_ID="$ACCOUNT_ID"

cd "$(git rev-parse --show-toplevel)"

banner "ClaimSale setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Prerequisites: gh, jq, pnpm, Node, cf"
say "This wizard uses the GitHub CLI (gh) and the Cloudflare CLI (cf) as you."
for tool in gh jq pnpm node git curl; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not installed. Install it and re-run."; exit 1; }
done
node_major=$(node -p 'process.versions.node.split(".")[0]')
node_minor=$(node -p 'process.versions.node.split(".")[1]')
if (( node_major < 22 || (node_major == 22 && node_minor < 23) || (node_major == 24 && node_minor < 22) )); then
  warn "cf needs Node 22.23+ or 24.22+ (you have $(node -v)). Switch Node (see .nvmrc) and re-run."
  exit 1
fi
if ! gh auth status >/dev/null 2>&1; then
  step "Signing in to GitHub with gh."
  gh auth login
fi
REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
note "GitHub repository: $REPO"
step "Installing dependencies (this also installs the pinned cf)."
pnpm install --frozen-lockfile
if ! pnpm exec cf auth whoami >/dev/null 2>&1; then
  step "Signing in to Cloudflare with cf. Approve the request in your browser."
  pnpm exec cf auth login
fi
pnpm exec cf auth whoami >/dev/null 2>&1 || { warn "cf is not signed in."; exit 1; }
note "cf is signed in."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GitHub: make dev the default branch"
say "New pull requests should target dev (main is production only)."
current=$(gh repo view "$REPO" --json defaultBranchRef --jq .defaultBranchRef.name)
if [[ "$current" == "dev" ]]; then
  note "dev is already the default branch."
elif confirm "Change the default branch from '$current' to 'dev'?"; then
  gh repo edit "$REPO" --default-branch dev >/dev/null
  printf '  %s✓%s default branch is now dev\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Make dev the default branch")
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "GitHub: protect dev"
say "A ruleset on dev: no deletion or force-push, changes through pull requests,"
say "and the four CI checks must pass. Repository admins (you) can bypass it."
for c in "${REQUIRED_CHECKS[@]}"; do step "$c"; done
ruleset=$(jq -n --argjson checks "$(printf '%s\n' "${REQUIRED_CHECKS[@]}" | jq -R '{context: .}' | jq -s .)" '{
  name: "dev",
  target: "branch",
  enforcement: "active",
  conditions: { ref_name: { include: ["refs/heads/dev"], exclude: [] } },
  bypass_actors: [{ actor_id: 5, actor_type: "RepositoryRole", bypass_mode: "always" }],
  rules: [
    { type: "deletion" },
    { type: "non_fast_forward" },
    { type: "pull_request", parameters: {
        required_approving_review_count: 0, dismiss_stale_reviews_on_push: false,
        require_code_owner_review: false, require_last_push_approval: false,
        required_review_thread_resolution: false, allowed_merge_methods: ["squash", "merge"] } },
    { type: "required_status_checks", parameters: {
        strict_required_status_checks_policy: false, required_status_checks: $checks } }
  ]
}')
existing_id=$(gh api "repos/$REPO/rulesets" --jq '.[] | select(.name == "dev") | .id' 2>/dev/null || true)
if confirm "${existing_id:+Update}${existing_id:-Create} the 'dev' ruleset?"; then
  if [[ -n "$existing_id" ]]; then
    printf '%s' "$ruleset" | gh api -X PUT "repos/$REPO/rulesets/$existing_id" --input - >/dev/null
  else
    printf '%s' "$ruleset" | gh api -X POST "repos/$REPO/rulesets" --input - >/dev/null
  fi
  printf '  %s✓%s dev is protected\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Protect dev with a ruleset")
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "GitHub: deployment environments"
say "preview (any branch), staging (dev only), production (main only, needs your approval)."
me_id=$(gh api user --jq .id)
put_env() { # name json
  printf '%s' "$2" | gh api -X PUT "repos/$REPO/environments/$1" --input - >/dev/null
}
only_branch() { # env branch
  local existing
  existing=$(gh api "repos/$REPO/environments/$1/deployment-branch-policies" --jq '.branch_policies[].name' 2>/dev/null || true)
  grep -qx "$2" <<<"$existing" || gh api -X POST "repos/$REPO/environments/$1/deployment-branch-policies" -f name="$2" -f type=branch >/dev/null
}
custom='{"deployment_branch_policy":{"protected_branches":false,"custom_branch_policies":true}}'
put_env preview '{}'
put_env staging "$custom"; only_branch staging dev
put_env production "$(jq -n --argjson id "$me_id" '{reviewers:[{type:"User",id:$id}],
  deployment_branch_policy:{protected_branches:false,custom_branch_policies:true}}')"
only_branch production main
printf '  %s✓%s environments preview, staging, production\n' "$GREEN" "$RESET"
note "Production deploys wait for your approval in the Actions tab."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: API token for CI"
say "CI deploys with wrangler and provisions with cf using one API token."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token → Create Custom Token. Name it: claimsale-ci"
step "Permissions (all Account-level): Workers Scripts: Edit, D1: Edit, Queues: Edit,"
step "  Account Settings: Read."
step "Account Resources: Include → AntiTcb. Leave Zone Resources empty (no domain yet)."
step "Continue to summary → Create Token → copy the token."
note "If a later deploy fails with a 403, its log names the missing permission; edit the token to add it."
ask_secret CLOUDFLARE_API_TOKEN "Paste the token (hidden):"
verify=$(curl -sS -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" https://api.cloudflare.com/client/v4/user/tokens/verify | jq -r '.result.status // "invalid"')
if [[ "$verify" != "active" ]]; then
  warn "Cloudflare says this token is '$verify'. Re-run the wizard with a valid token."
  exit 1
fi
note "Token verified (active)."
set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
set_var CLOUDFLARE_ACCOUNT_ID "$ACCOUNT_ID"
unset CLOUDFLARE_API_TOKEN
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: notification queues"
say "The engine Worker needs its queue to exist before the first deploy."
for q in claimsale-notifications-staging claimsale-notifications; do
  scripts/cf-resources.sh ensure-queue "$q"
  printf '  %s✓%s queue %s\n' "$GREEN" "$RESET" "$q"
done
note "Per-PR queues and databases are created and deleted by the preview workflows."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: workers.dev subdomain"
say "Staging and PR previews are served on <worker>.<subdomain>.workers.dev."
open_url "https://dash.cloudflare.com/$ACCOUNT_ID/workers-and-pages"
step "In Workers & Pages, find 'Subdomain' in the account details panel."
step "Copy only the part before .workers.dev (for example: antitcb)."
ask WORKERS_SUBDOMAIN "workers.dev subdomain:"
WORKERS_SUBDOMAIN="${WORKERS_SUBDOMAIN%.workers.dev}"
set_var WORKERS_SUBDOMAIN "$WORKERS_SUBDOMAIN"
set_var STAGING_URL "https://claimsale-web-staging.$WORKERS_SUBDOMAIN.workers.dev"
note "PRODUCTION_URL is set later, once claimsale.net is registered."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare Access: service token for CI"
say "CI's smoke tests sign in to Access-protected staging with a service token."
say "cf creates it and the values go straight into GitHub secrets; they're never shown."
if gh secret list --json name --jq '.[].name' | grep -qx ACCESS_CLIENT_ID && ! confirm "ACCESS_CLIENT_ID already exists. Create a new service token anyway?"; then
  note "Keeping the existing service token."
else
  tok=$(mktemp); chmod 600 "$tok"
  pnpm exec cf zero-trust access service-tokens create --name claimsale-ci --duration 8760h > "$tok"
  rows='if type == "object" and has("result") then .result else . end'
  set_secret ACCESS_CLIENT_ID "$(jq -r "$rows | .client_id" "$tok")"
  set_secret ACCESS_CLIENT_SECRET "$(jq -r "$rows | .client_secret" "$tok")"
  rm -f "$tok"
  note "The service token 'claimsale-ci' expires in 1 year; re-run this stage to rotate it."
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Renovate: dependency updates"
say "Renovate opens weekly update PRs against dev (renovate.json)."
open_url "https://github.com/apps/renovate"
step "Install (or Configure) → Only select repositories → choose ${REPO#*/} → Save."
step "Renovate opens an onboarding PR first; merge it to start updates."
pause "Press Enter once Renovate is installed"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "First staging deploy, then lock it with Access"
say "This runs the 'Deploy staging' workflow on dev."
if confirm "Start the staging deploy now?"; then
  gh workflow run deploy-staging.yml --repo "$REPO" --ref dev
  sleep 5
  run_id=$(gh run list --repo "$REPO" --workflow deploy-staging.yml --branch dev --limit 1 --json databaseId --jq '.[0].databaseId')
  note "Watching run $run_id (Ctrl+C stops watching, not the deploy)."
  gh run watch "$run_id" --repo "$REPO" --exit-status || warn "The staging deploy failed; open it with: gh run view $run_id --log-failed"
else
  SKIPPED+=("Run the staging deploy: gh workflow run deploy-staging.yml --ref dev")
fi
say ""
say "Now protect staging with Cloudflare Access:"
open_url "https://dash.cloudflare.com/$ACCOUNT_ID/workers/services/view/claimsale-web-staging/production/settings"
note "If that link 404s: Workers & Pages → claimsale-web-staging → Settings."
step "Domains & Routes → workers.dev → enable Cloudflare Access → Save."
step "Zero Trust → Access → Applications → open the new claimsale-web-staging app → Policies:"
step "  add a policy with Action 'Service Auth' that includes the service token 'claimsale-ci'."
step "Keep the default policy that allows your own email."
pause "Press Enter once Access is on"
SKIPPED+=("PR previews are not behind Access yet (each preview is a new Worker); revisit before previews hold real data")
SKIPPED+=("Create main and set PRODUCTION_URL once claimsale.net is registered")

finish
